function header(){document.documentElement.lang=language==='zh'?'zh-CN':'en';document.querySelector('header').innerHTML=`<a class="brand" href="#projects"><span class="brand-mark">F</span>FillOut</a><nav>${[['studio','Studio','工作室'],['projects','Projects','项目'],['market','Market','市场'],['data','Data','数据'],['wallet','My holdings','我的持仓'],['whitepaper','Whitepaper','白皮书']].map(([r,en,zh])=>`<a href="#${r}" class="${route()===r?'active':''}">${t(en,zh)}</a>`).join('')}</nav><div class="language-picker"><button data-lang="zh" class="${language==='zh'?'selected':''}">中文</button><span>/</span><button data-lang="en" class="${language==='en'?'selected':''}">EN</button></div><div class="wallet-controls">${account?`<span class="wallet-address">${short(account)}</span><button id="disconnect">${t('Disconnect','断开连接')}</button>`:`<button id="connect">${t('Connect wallet','连接钱包')}</button>`}</div>`;$('#connect')?.addEventListener('click',()=>connect().catch(error));$('#disconnect')?.addEventListener('click',()=>{walletSession.disconnect();toast('Wallet disconnected from this site.','钱包已与此网站断开连接。');});document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{setLanguage(b.dataset.lang);render();});document.querySelector('.network-bar').innerHTML=`<span>Robinhood Chain · <b>${t("Mainnet","主网")}</b></span>`;document.querySelector('footer').innerHTML=`<div class="footer-brand"><a href="#projects"><span class="brand-mark">F</span> FillOut</a><span>${t('Build logic. Keep the state.','构建逻辑，保存状态。')}</span></div><div class="footer-links"><a class="footer-icon-link " href="#whitepaper"  aria-label="${t('Protocol & fees','协议与费用')}" title="${t('Protocol & fees','协议与费用')}"><svg viewBox="0 0 24 24" width="21" height="21" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M4 3h12a3 3 0 0 1 3 3v15H6a3 3 0 0 1-3-3V6a3 3 0 0 1 3-3Z"/><path d="M3 17h16M7 7h8M7 11h6"/></svg><span>${t('Protocol & fees','协议与费用')}</span></a><a class="footer-icon-link " href="/security.html"  aria-label="${t('Security & Transparency','安全与透明度')}" title="${t('Security & Transparency','安全与透明度')}"><svg viewBox="0 0 24 24" width="21" height="21" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/></svg><span>${t('Security & Transparency','安全与透明度')}</span></a><a class="footer-icon-link " href="https://github.com/Filloutt/fillout/issues" target="_blank" rel="noopener" aria-label="${t('Report an issue','反馈问题')}" title="${t('Report an issue','反馈问题')}"><svg viewBox="0 0 24 24" width="21" height="21" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M4 4h16v13H9l-5 4V4Z"/><path d="M12 8v4M12 15h.01"/></svg><span>${t('Report an issue','反馈问题')}</span></a><a class="footer-icon-link icon-only" href="https://x.com/Fillout_rh" target="_blank" rel="noopener" aria-label="X" title="X"><svg viewBox="0 0 24 24" width="21" height="21" aria-hidden="true" fill="currentColor" ><path d="M18.9 2H22l-6.8 7.8L23.2 22h-6.3l-4.9-7.4L5.5 22H2.3l7.9-9L1 2h6.5l4.5 6.8L18.9 2ZM17.8 20h1.7L6.6 4H4.8l13 16Z"/></svg></a><a class="footer-icon-link icon-only" href="https://github.com/Filloutt/fillout" target="_blank" rel="noopener" aria-label="GitHub" title="GitHub"><svg viewBox="0 0 24 24" width="21" height="21" aria-hidden="true" fill="currentColor" ><path d="M12 .8a11.4 11.4 0 0 0-3.6 22.2c.6.1.8-.2.8-.5v-2.1c-3.2.7-3.9-1.4-3.9-1.4-.5-1.3-1.3-1.6-1.3-1.6-1.1-.8.1-.8.1-.8 1.2.1 1.8 1.2 1.8 1.2 1.1 1.8 2.8 1.3 3.4 1 .1-.8.4-1.3.7-1.6-2.6-.3-5.3-1.3-5.3-5.6 0-1.2.4-2.2 1.2-3-.1-.3-.5-1.5.1-3.1 0 0 1-.3 3.1 1.2a10.7 10.7 0 0 1 5.8 0c2.2-1.5 3.1-1.2 3.1-1.2.6 1.6.2 2.8.1 3.1.8.8 1.2 1.8 1.2 3 0 4.3-2.7 5.3-5.3 5.6.4.4.8 1.1.8 2.1v3.2c0 .3.2.6.8.5A11.4 11.4 0 0 0 12 .8Z"/></svg></a></div>`;}
function error(e){if(e?.code===4001)toast('Request cancelled in wallet.','已在钱包中取消请求。');else{const detail=String(e?.data?.message||e?.shortMessage||e?.message||'Unknown wallet or network error').replace(/^Error:\s*/,'').slice(0,180);toast('Request failed: '+detail,'请求失败：'+detail);}}
const walletSession=createWalletSession({getProvider:()=>{useProvider();return provider;},ensureNetwork,origin:location.origin,onChange:value=>{account=value;balances=null;chain=null;readId++;render();refresh();}});
function useProvider(){if(provider)return;provider=window.ethereum;if(!provider)throw Error(t("No wallet found. Open a wallet-enabled browser.","未检测到钱包，请使用支持钱包的浏览器。"));provider.on?.('accountsChanged',a=>walletSession.accountsChanged(a));provider.on?.('disconnect',()=>walletSession.unavailable());provider.on?.('connect',()=>walletSession.restore());provider.on?.('chainChanged',()=>{balances=null;chain=null;refresh();document.querySelectorAll('[data-refresh-parts]').forEach(b=>b.click());});}
let connectionRequest=null;
function connect(){
 if(account)return Promise.resolve(account);
 if(connectionRequest)return connectionRequest;
 connectionRequest=new Promise((resolve,reject)=>{
 const dialog=document.createElement('dialog');
 dialog.setAttribute('aria-labelledby','wallet-dialog-title');
 dialog.innerHTML='<h2 id="wallet-dialog-title">'+t('Connect your wallet','连接您的钱包')+'</h2><p>'+t('Confirm the connection with a message signature in your wallet. This does not cost gas or give permission to move your tokens.','请在钱包中签署消息以确认连接。此操作不收取网络费，也不会授权转移您的代币。')+'</p><p>'+t('Disconnect ends your session on this site. Existing token approvals remain unchanged.','断开连接会结束您在此网站的会话，但不会撤销已有的代币授权。')+'</p><p class="wallet-progress" role="status"></p><div class="actions"><button data-cancel>'+t('Cancel','取消')+'</button><button class="primary" data-confirm>'+t('Continue in wallet','在钱包中继续')+'</button></div>';
 document.body.append(dialog);dialog.showModal();
 let settled=false;
 const cancel=()=>{if(settled)return;settled=true;walletSession.disconnect();dialog.close();dialog.remove();reject(Object.assign(Error('Connection cancelled.'),{code:4001}));};
 dialog.querySelector('[data-cancel]').onclick=cancel;
 dialog.addEventListener('cancel',e=>{e.preventDefault();cancel();});
 dialog.querySelector('[data-confirm]').onclick=async()=>{
 const button=dialog.querySelector('[data-confirm]');button.disabled=true;
 dialog.querySelector('.wallet-progress').textContent=t('Confirm the message in your wallet…','请在钱包中确认消息…');
 try{const address=await walletSession.connect();if(settled)return;settled=true;dialog.close();dialog.remove();await refresh();resolve(address);}catch(e){if(settled)return;settled=true;dialog.close();dialog.remove();reject(e);}
 };
 }).finally(()=>{connectionRequest=null;});
 return connectionRequest;
}
async function ensureNetwork(){const expected=hex(config.chainId);if(Number(await provider.request({method:'eth_chainId'}))!==config.chainId){try{await provider.request({method:'wallet_switchEthereumChain',params:[{chainId:expected}]});}catch(e){if(e.code!==4902)throw e;await provider.request({method:'wallet_addEthereumChain',params:[{chainId:expected,chainName:config.chainName,rpcUrls:[config.rpcUrl],blockExplorerUrls:[config.explorerUrl],nativeCurrency:{name:'Ether',symbol:'ETH',decimals:18}}]});}if(Number(await provider.request({method:'eth_chainId'}))!==config.chainId)throw Error(t("Switch to the correct network.","请切换到正确的网络。"));}}
async function rpc(method,params){
 if(provider){try{if(Number(await provider.request({method:'eth_chainId'}))===config.chainId)return await provider.request({method,params});}catch{}}
 const response=await fetch(config.rpcUrl,{method:'POST',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',id:Date.now(),method,params}),signal:AbortSignal.timeout(12000)});
 if(!response.ok)throw Error('Network unavailable');const json=await response.json();if(json.error)throw Error(json.error.message||'Network read failed');return json.result;
}
const call=(to,data)=>rpc('eth_call',[{to,data},'latest']);
async function refresh(){const config=projectConfigs[currentProject()];const id=++readId;try{const p=config.partsAddress,d=config.deskAddress;const values=await Promise.all(['0x5df0df80','0x4facfe37','0xbdf7f54e','0xb10b69cc'].map(s=>call(p,s)));const [price,owner,parts,code]=await Promise.all([call(d,'0xe73faa2d'),call(p,'0x8da5cb5b'),call(d,'0x'+config.partsSelector),rpc('eth_getCode',[d,'latest'])]);if(code==='0x'||('0x'+owner.slice(-40)).toLowerCase()!==d.toLowerCase()||('0x'+parts.slice(-40)).toLowerCase()!==p.toLowerCase())throw Error('contract');const locked=config.circuitsAddress?await Promise.all([0,1].map(i=>call(config.partsAddress,'0x00fdd58e'+config.circuitsAddress.slice(2).toLowerCase().padStart(64,'0')+word(i)).then(BigInt))):[0n,0n];const next={caps:values.slice(0,2).map(BigInt),minted:values.slice(2).map(BigInt),locked,price:BigInt(price)};let nextBalances=null;if(account){const address=account.slice(2).toLowerCase().padStart(64,'0');nextBalances=await Promise.all([0,1].map(i=>call(p,'0x00fdd58e'+address+word(i)).then(BigInt)));}if(id!==readId)return;chain=next;balances=nextBalances;loadError=false;}catch{if(id!==readId)return;loadError=true;chain=null;balances=null;}if(/^(?:(?:fillout|openbook|mint)-[01]|foundry|data|projects)$/.test(route()))render();}
const badge=()=>`<span class="official">${t('Official','官方')}</span>`;
const intro=(en,zh,subEn,subZh,showEyebrow=true)=>`<div class="page-heading">${showEyebrow?'<div class="eyebrow">FILLOUT / OPENBOOK</div>':''}<h1>${t(en,zh)}</h1><p class="muted">${t(subEn,subZh)}</p></div>`;
const progress=i=>chain?remaining(chain.caps[i],chain.minted[i]).toLocaleString('en-US'):'—';
const mintCounter=i=>(chain?chain.minted[i].toLocaleString('en-US'):'—')+' '+t('minted','已铸造')+' · '+progress(i)+' '+t('remaining','剩余');
function projects(){app.innerHTML=`<section class="start-guide"><h1>${t('Build your first logic circuit','构建你的第一个逻辑电路')}</h1><p>${t('Quote handles logic. Settle remembers one bit. Connect them in Studio and see your design work.','Quote 处理逻辑，Settle 保存一位状态。在工作室连接组件，观察电路运行。')}</p><a class="primary link-button" href="#studio">${t('Try without a wallet','无需钱包即可体验')}</a><p class="hint">${t('Design and simulation are free. Minting parts and creating circuit NFTs are separate mainnet transactions.','设计和模拟免费。铸造组件及创建电路 NFT 是独立的主网交易。')}</p></section>`+intro('Collections','系列','OpenBook and FillOut use the same logic tools, but have separate parts, markets and circuit contracts. Parts from different collections cannot be combined in one circuit NFT.','OpenBook 与 FillOut 使用相同的逻辑工具，但组件、市场和电路合约独立。不同系列的组件不能合并到同一个电路 NFT。',false)+'<div class="project-list">'+['openbook','fillout'].map(k=>'<article class="project-row"><div><h2>'+projectName(k)+' '+badge()+'</h2><p>Quote · Settle</p><p class="muted">'+t("Robinhood Chain Mainnet","Robinhood Chain 主网")+'</p></div><div><strong id="supply-'+k+'">'+t("Loading…","加载中…")+'</strong><p>'+t("Total minted / lifetime cap","累计铸造 / 铸造上限")+'</p></div><a class="primary link-button" href="#'+k+'-0">'+t("View project ↗","查看项目 ↗")+'</a></article>').join('')+'</div>';for(const k of ['openbook','fillout']){const el=$('#supply-'+k);readProject(k).then(s=>{if(el.isConnected)el.textContent=(s.minted[0]+s.minted[1]).toLocaleString('en-US')+' / '+(s.caps[0]+s.caps[1]).toLocaleString('en-US');}).catch(()=>{if(el.isConnected)el.textContent=t("Data unavailable","数据暂不可用");});}}

function market(){app.innerHTML=intro('Market','市场','Choose a project and part to trade.','选择项目和组件进行交易。')+['openbook','fillout'].map(k=>{const c=projectConfigs[k];return walletPartsMarkup(k)+'<section class="market-project-head"><div class="project-mark">'+projectName(k)[0]+'</div><div><h2>'+projectName(k)+' '+badge()+'</h2><small>'+short(c.marketAddress)+'</small></div></section><div class="asset-market-list">'+names.map((n,i)=>'<a class="asset-market-row" href="#market-'+k+'-'+i+'"><div class="asset-glyph">'+(i?'▣':'⊼')+'</div><div><h2>'+n+' '+badge()+'</h2><p>'+(i?t("Memory · one bit of state","存储器 · 一位状态"):t("NAND logic · two inputs, one output","与非逻辑 · 两个输入，一个输出"))+'</p><small>'+short(c.partsAddress)+' · '+t('Token ID','代币编号')+' '+i+'</small></div><div class="asset-stat"><strong id="market-supply-'+k+'-'+i+'">'+t("Loading…","加载中…")+'</strong><span>'+t("minted / cap","已铸造 / 上限")+'</span></div><span class="asset-arrow">'+t("Open market ↗","进入市场 ↗")+'</span></a>').join('')+'</div>';}).join('');for(const k of ['openbook','fillout'])readProject(k).then(s=>names.forEach((n,i)=>{const el=$('#market-supply-'+k+'-'+i);if(el)el.textContent=s.minted[i].toLocaleString('en-US')+' / '+s.caps[i].toLocaleString('en-US');})).catch(()=>names.forEach((n,i)=>{const el=$('#market-supply-'+k+'-'+i);if(el)el.textContent=t("Data unavailable","数据暂不可用");}));for(const k of ['openbook','fillout'])attachWalletParts(k);}

function walletPartsMarkup(project,selected=null){
  return `<section class="wallet-inventory" data-inventory="${project}"><div class="inventory-heading"><h2>${t('In your wallet','钱包中的组件')} · ${projectName(project)}</h2><button data-refresh-parts>${t('Refresh balances','刷新余额')}</button></div><p class="muted">${t('Available to sell or use in a circuit. Listed or locked parts are not in this wallet.','可出售或用于电路的组件。已挂单或锁定的组件不在钱包余额中。')}</p><div class="wallet-parts">${names.map((name,id)=>`<a class="wallet-part ${selected===id?'selected':''}" href="#market-${project}-${id}" data-wallet-part="${id}"><span>${name}</span><strong data-wallet-count>${account?t('Loading…','加载中…'):'—'}</strong><span>${t('Available to sell','可出售')}</span></a>`).join('')}</div><p data-inventory-status role="status"></p>${!account?`<button data-connect-parts>${t('Connect to see your balances','连接钱包以查看余额')}</button>`:''}</section>`;
}
function attachWalletParts(project,onAmounts=()=>{}){
  const box=app.querySelector(`[data-inventory="${project}"]`),owner=account;
  if(!box)return;
  let request=0;
  box.querySelector('[data-connect-parts]')?.addEventListener('click',()=>connect().catch(error));
  const load=async()=>{
    if(!owner)return;
    const version=++request,button=box.querySelector('[data-refresh-parts]');button.disabled=true;
    box.querySelector('[data-inventory-status]').textContent=t('Updating balances…','正在更新余额…');
    onAmounts(null);
    const amounts=await readParts({call,partsAddress:projectConfigs[project].partsAddress,owner});
    if(!box.isConnected||account!==owner||request!==version)return;
    amounts.forEach((result,id)=>{box.querySelector(`[data-wallet-part="${id}"] [data-wallet-count]`).textContent=result.error?t('Unavailable','暂不可用'):result.amount.toLocaleString('en-US');});
    box.querySelector('[data-inventory-status]').textContent=amounts.some(r=>r.error)?t('Some balances could not be loaded. Retry with Refresh balances.','部分余额无法加载，请点击“刷新余额”重试。'):t('Live wallet balance · ','实时钱包余额 · ')+short(owner);
    button.disabled=false;onAmounts(amounts);
  };
  box.querySelector('[data-refresh-parts]').disabled=!owner;
  box.querySelector('[data-refresh-parts]').onclick=load;
  load();
  return load;
}
function holdings(){
  app.innerHTML=intro('My holdings','我的持仓','Parts and circuit NFTs for both projects.','两个项目的组件和电路 NFT。')+
    ['openbook','fillout'].map(k=>walletPartsMarkup(k)+`<section class="holdings-box"><h3>${projectName(k)} · ${t('Circuit NFTs','电路 NFT')}</h3><div id="circuits-${k}">${account?t('Loading NFTs…','正在加载 NFT…'):t('Connect your wallet to see your circuit NFTs.','连接钱包以查看您的电路 NFT。')}</div></section>`).join('');
  for(const k of ['openbook','fillout']){attachWalletParts(k);if(account)loadCircuitHoldings(k);}
}
async function loadCircuitHoldings(project,before=null){
  const box=$('#circuits-'+project),owner=account,c=projectConfigs[project];
  if(!box||!owner)return;
  box.textContent=t('Loading NFTs…','正在加载 NFT…');
  try{
    const page=await readCircuitPage({call,circuitsAddress:c.circuitsAddress,owner,before});
    if(!box.isConnected||account!==owner)return;
    box.innerHTML=`<p>${t('Owned circuit NFTs','持有的电路 NFT')}: <strong>${page.owned.toLocaleString('en-US')}</strong></p>`+
      (page.ids.length?page.ids.map(id=>`<article class="holding-row"><span>${projectName(project)} Circuit #${id}</span><a target="_blank" rel="noopener" href="${c.explorerUrl}/token/${c.circuitsAddress}?a=${id}">${t('View NFT ↗','查看 NFT ↗')}</a></article>`).join(''):
      `<p>${page.owned?t('No owned NFTs in this ID range.','此编号范围内没有您持有的 NFT。'):t('No circuit NFTs in this wallet.','此钱包暂无电路 NFT。')}</p>`)+
      `<div class="actions">${page.hasOlder?`<button data-older>${t('Check older IDs','查看更早的编号')}</button>`:''}${before!==null?`<button data-latest>${t('Latest IDs','最新编号')}</button>`:''}<button data-retry>${t('Refresh NFTs','刷新 NFT')}</button></div>`;
    box.querySelector('[data-older]')?.addEventListener('click',()=>loadCircuitHoldings(project,page.start));
    box.querySelector('[data-latest]')?.addEventListener('click',()=>loadCircuitHoldings(project));
    box.querySelector('[data-retry]').onclick=()=>loadCircuitHoldings(project,before);
  }catch{
    if(!box.isConnected||account!==owner)return;
    box.innerHTML=`<p>${t('Circuit NFTs are temporarily unavailable. Your part balances are shown separately above.','电路 NFT 暂不可用。组件余额已在上方单独显示。')}</p><button data-retry>${t('Retry NFTs','重试 NFT')}</button>`;
    box.querySelector('[data-retry]').onclick=()=>loadCircuitHoldings(project,before);
  }
}

function mintPage(i,project="openbook"){const selected=projectConfigs[project];  const live=true,projectName=project==="fillout"?"FillOut":"OpenBook";const price=chain?.price||200000000000000n;app.innerHTML=intro(projectName,projectName,projectName+' · Quote / Settle',projectName+' · Quote / Settle')+`<div class="mint-layout"><section class="part-overview"><div class="part-symbol">${i===0?'⊼':'▣'}</div><h2>${names[i]} ${badge()}</h2><p>${i===0?t('Two inputs, one NAND output. Connect Quote gates to build combinational circuits.','两个输入，一个 NAND 输出。连接 Quote 门以构建组合电路。'):t('One bit of memory. Settle stores state between simulation steps.','一位存储器。Settle 在模拟步骤之间保存状态。')}</p><p>${live?mintCounter(i):t('Supply pending deployment','供应量待部署')}</p><p id="collection-holders" class="muted" title="${t('Collection-wide address count from the explorer; may include contracts and indexing delays.','浏览器统计的整个系列持有地址数，可能包括合约地址并存在索引延迟。')}">${t('Collection holders','系列持有地址')}: …</p><a class="text-link" href="#studio">${t('Open in Studio','在工作室中打开')} ↗</a></section><section class="mint-panel"><div class="part-tabs">${names.map((n,j)=>`<a class="link-button ${i===j?'primary':''}" href="#${project}-${j}">${t('Mint','铸造')} ${n}</a>`).join('')}</div><h2>${t('Mint','铸造')} ${names[i]}</h2><label class="amount-label" for="quantity">${t('Quantity','数量')}</label><input id="quantity" type="number" min="1" max="50000" step="1" value="${quantity}" ${busy?'disabled':''}><div class="quantity-presets">${[1,10,100].map(q=>`<button data-quantity="${q}" ${busy?'disabled':''}>${q}</button>`).join('')}</div><div class="costs"><div><span>${t('Unit price','单价')}</span><strong>${live?fmt(price)+' ETH':t('Not announced','尚未公布')}</strong></div><div><span>${t('Parts subtotal','组件小计')}</span><strong id="subtotal">${live?fmt(price*BigInt(quantity))+' ETH':'—'}</strong></div><div><span>${t('Platform fee','平台费用')}</span><strong>${t('Estimated at mint','铸造时估算')}</strong></div></div><p class="small-note">${t('An estimated network-equivalent platform fee is added. Wallet network fees are charged separately.','另加等于预估网络费的平台费用。钱包网络费单独收取。')}</p><button id="mint" class="primary" ${busy||!live?'disabled':''}>${busy?t('Waiting for wallet…','等待钱包…'):t('Mint','铸造')+' '+names[i]}</button><p class="small-note">${t('Opens your wallet directly.','直接打开钱包。')}</p><div id="mint-status" role="status">${lastTx?txLink():''}</div></section></div>`;const holderEl=$('#collection-holders');collectionHolders(selected.explorerUrl,selected.partsAddress).then(n=>{if(holderEl?.isConnected)holderEl.textContent=t('Collection holders','系列持有地址')+': '+n.toLocaleString('en-US');}).catch(()=>{if(holderEl?.isConnected)holderEl.textContent=t('Collection holders: unavailable','系列持有地址：暂不可用');});$('#quantity').onchange=e=>{quantity=Math.min(50000,Math.max(1,Math.floor(Number(e.target.value)||1)));e.target.value=quantity;$('#subtotal').textContent=live?fmt(price*BigInt(quantity))+' ETH':'—';};document.querySelectorAll('[data-quantity]').forEach(b=>b.onclick=()=>{quantity=Number(b.dataset.quantity);mintPage(i,project);});$('#mint').onclick=()=>{if(live)mint(i);};}
function txLink(){return `<a class="text-link" href="${config.explorerUrl}/tx/${lastTx.hash}" target="_blank" rel="noopener">${lastTx.status==='confirmed'?t('Mint confirmed','铸造已确认'):lastTx.status==='failed'?t('Transaction reverted','交易已回滚'):t('Transaction submitted · view status','交易已提交 · 查看状态')} ↗</a>`;}
async function mint(i){const config=projectConfigs[currentProject()];if(busy)return;busy=true;render();try{if(!account)await connect();else await ensureNetwork();await refresh();if(!chain)throw Error(t("Unable to read contract data. Please retry.","无法读取合约数据，请重试。"));if(config.partsAddress!==projectConfigs[currentProject()].partsAddress)throw Error(t("Project changed. Retry mint.","项目已更改，请重新铸造。"));const sender=account,q=BigInt(quantity);if(q<=0n||q+chain.minted[i]>chain.caps[i])throw Error(t("Quantity exceeds the mint limit.","数量超过铸造上限。"));const base=chain.price*q;const gasPrice=BigInt(await provider.request({method:'eth_gasPrice'}));let fee=gasPrice*100000n;for(let j=0;j<2;j++){const gas=BigInt(await provider.request({method:'eth_estimateGas',params:[{from:sender,to:config.deskAddress,data:buyData(i,q,fee),value:hex(base+fee)}]}));fee=gas*gasPrice;}const accounts=await provider.request({method:'eth_accounts'});if(accounts[0]?.toLowerCase()!==sender.toLowerCase()||Number(await provider.request({method:'eth_chainId'}))!==config.chainId)throw Error(t("Wallet account or network changed. Please retry.","钱包账户或网络已更改，请重试。"));if(!window.confirm(t('Review mint estimate','确认铸造估算')+'\n'+names[i]+' × '+q+'\n'+t('Parts subtotal: ','组件小计：')+fmt(base)+' ETH\n'+t('Platform fee: ','平台费用：')+fmt(fee)+' ETH\n'+t('Transaction value: ','交易金额：')+fmt(base+fee)+' ETH\n'+t('Estimated network fee (additional): ','预估网络费（另计）：')+fmt(fee)+' ETH\n'+t('Estimated total: ','预计总费用：')+fmt(base+fee*2n)+' ETH\n\n'+t('Network fees may change. Review the final amount in your wallet. Continue?','网络费用可能变化。请在钱包中核对最终金额。继续？')))return;const hash=await provider.request({method:'eth_sendTransaction',params:[{from:sender,to:config.deskAddress,value:hex(base+fee),data:buyData(i,q,fee)}]});lastTx={hash,status:'pending'};poll(hash);}catch(e){error(e);}finally{busy=false;render();}}
async function waitReceipt(hash){for(let i=0;i<40;i++){const r=await rpc('eth_getTransactionReceipt',[hash]);if(r)return r;if(i<39)await new Promise(x=>setTimeout(x,1500));}throw Error(t("Confirmation is taking longer than expected. Check the transaction before retrying.","确认时间较长，请先查看交易状态，再决定是否重试。"));}
async function poll(hash){for(let i=0;i<40;i++){try{const receipt=await rpc('eth_getTransactionReceipt',[hash]);if(receipt){lastTx={hash,status:Number(receipt.status)===1?'confirmed':'failed'};await refresh();if(['wallet','airdrop','market'].includes(route())||route().startsWith('market-'))render();return;}}catch{}await new Promise(r=>setTimeout(r,3000));}}
function dataPage(){app.innerHTML=intro('Protocol data','协议数据','Supply caps and contract references by project.','项目供应上限与合约地址。')+'<div class="guide">'+['openbook','fillout'].map(k=>{const c=projectConfigs[k];return '<article><h2>'+projectName(k)+'</h2><p>'+(k==='openbook'?'Quote 78,261 · Settle 21,739 · '+t('Total','总量')+' 100,000':'Quote 31,304 · Settle 8,696 · '+t('Total','总量')+' 40,000')+'</p>'+[[t('Parts','组件'),'partsAddress'],[t('Mint desk','铸造合约'),'deskAddress'],[t('Market','市场'),'marketAddress'],[t('Circuits','电路'),'circuitsAddress']].map(([label,key])=>'<p>'+label+'<br><a class="address" href="'+c.explorerUrl+'/address/'+c[key]+'" target="_blank" rel="noopener">'+c[key]+'</a></p>').join('')+'</article>';}).join('')+'</div>';}

function whitepaper(){const sections=[[t("Projects and supply","项目与供应量"),t("OpenBook and FillOut are separate ERC-1155 collections on Robinhood Chain Mainnet. OpenBook: 78,261 Quote and 21,739 Settle. FillOut: 31,304 Quote and 8,696 Settle. The ratio is approximately 3.6:1; caps are lifetime mint limits.","OpenBook 和 FillOut 是 Robinhood Chain 主网上两个独立的 ERC-1155 系列。OpenBook：78,261 个 Quote 和 21,739 个 Settle。FillOut：31,304 个 Quote 和 8,696 个 Settle。比例约为 3.6:1；这些上限指累计铸造上限。")],[t("Studio","工作室"),t("Choose OpenBook or FillOut before creating a circuit NFT. Quote is a NAND gate; Settle stores one bit. Step advances memory once. Reset simulation clears inputs and memory while keeping your design. Drafts are saved in this browser; export a backup.","创建电路 NFT 前，请选择 OpenBook 或 FillOut。Quote 是与非门；Settle 存储一位状态。运行一步会更新一次存储状态。重置模拟会将输入和存储状态归零，同时保留电路设计。草稿保存在此浏览器中，请导出备份。")],[t("Circuit NFTs","电路 NFT"),t("Creating a circuit NFT permanently locks the required parts from the selected collection in its circuit contract. Parts cannot be recovered. Simulation runs locally in Studio; it does not automatically advance on blockchain blocks.","创建电路 NFT 会将所选系列中所需数量的组件永久锁定在对应电路合约中，无法取回。模拟在工作室本地运行，不会随区块自动推进。")],[t("Minting and trading","铸造与交易"),t("The configured mint unit price is 0.0002 ETH. Minting adds an estimated network-equivalent platform fee; wallet network fees are separate. Market purchases use existing sell listings. Both projects have separate market contracts.","当前配置的铸造单价为 0.0002 ETH。铸造时另收与预估网络费等额的平台费用；钱包网络费单独收取。市场购买通过现有卖单进行。两个项目使用独立的市场合约。")],[t("Project status","项目状态"),t("Official identifies this project’s collections and does not imply Robinhood endorsement. Deployment alone is not an independent security audit.","“官方”表示本项目发行的系列，不代表 Robinhood 的认可。合约已部署不等同于通过独立安全审计。")]];app.innerHTML=intro('Whitepaper','白皮书','Current project behavior.','当前项目说明。')+technicalFigures()+'<div class="guide">'+sections.map(([h,p])=>'<article><h2>'+h+'</h2><p>'+p+'</p></article>').join('')+'</div>';}
let ethUsd=null,ethUsdAt=0;
function listingKey(id){return 'listing-'+config.chainId+'-'+config.marketAddress.toLowerCase()+'-'+id;}
function usdMarkup(eth){return '<small class="listing-usd" data-eth-usd="'+eth+'">'+(ethUsd?'≈ '+new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:4}).format(Number(eth)*ethUsd):t('USD rate unavailable','美元汇率暂不可用'))+'</small>';}
async function updateEthUsd(){try{const r=await fetch('https://api.coinbase.com/v2/prices/ETH-USD/spot',{cache:'no-store',signal:AbortSignal.timeout(8000)});if(!r.ok)throw Error('rate');const j=await r.json();const rate=Number(j.data?.amount);if(!(rate>0))throw Error('rate');ethUsd=rate;ethUsdAt=Date.now();}catch{if(Date.now()-ethUsdAt>120000)ethUsd=null;}document.querySelectorAll('[data-eth-usd]').forEach(el=>{el.textContent=ethUsd?'≈ '+new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:4}).format(Number(el.dataset.ethUsd)*ethUsd):t('USD rate unavailable','美元汇率暂不可用');});}
setInterval(()=>{if($('#listing-box'))updateEthUsd();},60000);
function listingMarkup(id,provided){const rows=provided??[];return rows.length?'<div class="listing-grid">'+rows.map(x=>{const pending=x.listingId==='pending',valid=/^\d+$/.test(x.listingId||'')&&/^\d+$/.test(x.priceWei||'');const unit=x.priceWei?fmt(BigInt(x.priceWei)):x.price;const total=x.priceWei?fmt(BigInt(x.priceWei)*BigInt(x.amount)):String(Number(unit)*Number(x.amount));return '<article class="listing-card"><div class="listing-art"><svg viewBox="0 0 240 150" role="img" aria-label="'+names[id]+' circuit"><path d="M30 55H80 M30 95H80 M158 75H210"/><rect x="80" y="30" width="78" height="90"/><path class="chip-accent" d="M83 32V118"/><text x="119" y="80" text-anchor="middle">'+names[id]+'</text><text x="30" y="45">A</text><text x="30" y="116">B</text><text x="205" y="65">Q</text></svg></div><div class="listing-content"><div class="listing-title"><strong>'+projectName(currentProject())+'</strong><span>'+names[id]+'</span></div><p class="listing-id">'+t('Listing','挂单')+' '+(pending?t('pending','待确认'):'#'+esc(x.listingId))+'</p><div class="listing-price"><strong>'+esc(unit)+' ETH</strong><span> / '+t('unit','单位')+'</span>'+usdMarkup(unit)+'</div><dl class="listing-details"><div><dt>'+t('Quantity remaining','剩余数量')+'</dt><dd>'+esc(x.amount)+' '+names[id]+'</dd></div><div><dt>'+t('Seller','卖家')+'</dt><dd><a href="'+config.explorerUrl+'/address/'+esc(x.seller)+'" target="_blank" rel="noopener" title="'+esc(x.seller)+'">'+short(x.seller)+'</a></dd></div><div><dt>'+t('Status','状态')+'</dt><dd class="listing-state">'+(pending?t('PENDING','待确认'):t('ACTIVE','有效'))+'</dd></div><div><dt>'+t('Buy all · total','全部购买 · 总计')+'</dt><dd>'+esc(total)+' ETH'+usdMarkup(total)+'</dd></div></dl><p class="listing-gas">'+t('Network fee charged separately','网络费另计')+'</p><button class="primary listing-buy" '+(!valid||pending?'disabled':'')+' data-buy-listing="'+esc(x.listingId||'pending')+'" data-buy-amount="'+esc(x.amount)+'" data-buy-price="'+esc(x.priceWei||'')+'">'+t('Buy','购买')+'</button></div></article>';}).join('')+'</div><p class="listing-rate-note">'+t('USD estimate uses the live ETH/USD spot rate from Coinbase, refreshed every minute. ','美元估值使用 Coinbase 实时 ETH/USD 汇率，每分钟刷新。')+'</p>':'<div class="market-empty">'+t('No active listings yet.','暂无有效挂单。')+'</div>';}
const buyingListings=new Set();
function syncBuyButtons(){document.querySelectorAll('[data-buy-listing]').forEach(b=>{if(buyingListings.has(b.dataset.buyListing)){b.disabled=true;b.textContent=t('Confirming…','确认中…');}});}
async function buyListing(id,listingId,amount,priceWei){const config=projectConfigs[currentProject()];if(buyingListings.has(listingId))return;buyingListings.add(listingId);syncBuyButtons();try{if(listingId==='pending')return toast('Listing is still confirming on-chain.','挂单仍在链上确认中。');if(!account)await connect();await ensureNetwork();const sender=account;const current=await rpc('eth_call',[{to:config.marketAddress,data:'0xde74e57b'+word(listingId)},'latest']);const w=current.slice(2).match(/.{64}/g);if(!w||w.length<5)throw Error(t("Unable to verify listing.","无法验证挂单。"));if(BigInt('0x'+w[4])===0n||BigInt('0x'+w[2])<BigInt(amount)||BigInt('0x'+w[3])!==BigInt(priceWei)){toast('Listing changed or sold. The market has been refreshed.','挂单已变更或售出，市场已刷新。');return;}const total=BigInt(priceWei)*BigInt(amount);const tx={from:sender,to:config.marketAddress,data:'0xd6febde8'+word(listingId)+word(amount),value:hex(total)};tx.gas=hex(BigInt(await provider.request({method:'eth_estimateGas',params:[tx]}))*120n/100n);tx.gasPrice=await provider.request({method:'eth_gasPrice'});await assertWalletContext(sender,config.chainId);const hash=await provider.request({method:'eth_sendTransaction',params:[tx]});toast('Purchase submitted. Waiting for confirmation…','购买已提交，等待确认…');const receipt=await waitReceipt(hash);if(Number(receipt.status)!==1)throw Error(t("Purchase reverted. The listing may have changed.","购买已回滚，挂单可能已变更。"));toast('Purchase confirmed.','购买已确认。');document.querySelectorAll('[data-refresh-parts]').forEach(b=>b.click());}catch(e){error(e);}finally{buyingListings.delete(listingId);await loadChainListings(id);}}
function refreshVisibleListings(){if(document.hidden)return;const match=route().match(/^market-(openbook|fillout)(?:-([01]))?$/);if(match&&$('#listing-box'))loadChainListings(Number(match[2]||0),true);}
setInterval(refreshVisibleListings,10000);window.addEventListener('focus',refreshVisibleListings);
let listingReadVersion=0;
async function marketRead(method,params){const response=await fetch(config.rpcUrl,{method:'POST',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',id:Date.now(),method,params}),signal:AbortSignal.timeout(12000)});if(!response.ok)throw Error('Market network unavailable');const json=await response.json();if(json.error)throw Error(json.error.message||'Market read failed');return json.result;}
const listingRefreshGate=createRefreshGate();
let listingCursor=null,listingPages=[];
async function loadChainListings(id,background=false){const project=currentProject(),box=$('#listing-box'),cursor=listingCursor;return listingRefreshGate(project+':'+id,()=>{if(currentProject()!==project||!box?.isConnected||cursor!==listingCursor)return true;return scanChainListings(id,box,cursor);},{background});}
async function scanChainListings(id,box,cursor){const c=projectConfigs[currentProject()];const version=++listingReadVersion;
 const current=()=>version===listingReadVersion&&box.isConnected&&cursor===listingCursor;
 box.querySelectorAll('[data-page]').forEach(b=>b.disabled=true);
 try{
 const page=await readListingPage({read:marketRead,to:c.marketAddress,tokenId:id,before:cursor});
 if(!current())return true;
 box.innerHTML=(page.rows.length?listingMarkup(id,page.rows):'<p>'+(page.hasOlder?t('No active listings in this range. Check older listings.','此范围内没有有效挂单，请查看更早的挂单。'):t('No active listings in this range.','此范围内没有有效挂单。'))+'</p>')+
 '<div class="actions"><button data-page="newer" '+(!listingPages.length?'disabled':'')+'>'+t('Newer','较新')+'</button><button data-page="older" '+(!page.hasOlder?'disabled':'')+'>'+t('Older','更早')+'</button><button data-page="latest">'+t('Latest','最新')+'</button></div>';
 box.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{if(b.dataset.page==='older'){listingPages.push(listingCursor);listingCursor=page.start;}else if(b.dataset.page==='newer')listingCursor=listingPages.pop()??null;else{listingCursor=null;listingPages=[];}loadChainListings(id);});
 syncBuyButtons();updateEthUsd();return true;
 }catch(e){if(!current())return false;box.innerHTML='<p>'+t('Unable to load current listings.','无法加载最新挂单。')+'</p><button data-retry>'+t('Retry','重试')+'</button>';box.querySelector('[data-retry]').onclick=()=>loadChainListings(id);return false;}}
const marketDrafts=new Map();
let listingInProgress=false;
function marketDetail(routeKey){
  listingCursor=null;listingPages=[];
  const [project,part]=routeKey.split('-'),id=part==='1'?1:0,c=projectConfigs[project];
  const draftKey=(account||'guest').toLowerCase()+':'+project+':'+id;
  if(!marketDrafts.has(draftKey))marketDrafts.set(draftKey,{price:'',quantity:'1',tab:'buy'});
  const draft=marketDrafts.get(draftKey);
  let available=null;
  app.innerHTML=intro(projectName(project),projectName(project),'Peer-to-peer market · '+names[id],'点对点市场 · '+names[id])+walletPartsMarkup(project,id)+
    `<div class="trade-tabs"><button class="trade-tab" data-trade="buy">${t('Buy','购买')}</button><button class="trade-tab" data-trade="sell">${t('Sell','出售')}</button></div>
    <section class="market-card trade-pane" data-pane="buy"><h2>${t('Buy','购买')} ${names[id]}</h2><p class="muted">${t('Choose an active listing below.','选择下方的有效挂单。')}</p></section>
    <section class="market-card trade-pane" data-pane="sell"><h2>${t('Sell','出售')} ${names[id]}</h2><p id="sell-available" class="sell-available" role="status"></p>
    <div class="market-form"><label>${t('Price per unit (ETH)','单价（ETH）')}<input id="sell-price" inputmode="decimal" placeholder="0.0003" value="${esc(draft.price)}"></label>
    <label>${t('Quantity','数量')}<div class="quantity-with-max"><input id="sell-amount" type="text" inputmode="numeric" value="${esc(draft.quantity)}"><button id="sell-max" type="button">${t('Max','最大')}</button></div></label></div>
    <p id="sell-validation" role="status"></p><button id="sell-submit" class="primary">${t('Approve and list','授权并挂单')}</button><p id="market-status" class="small-note" role="status"></p></section>
    <section class="market-card"><h2>${t('Listings','挂单')}</h2><div id="listing-box"><p>${t('Loading listings…','正在加载挂单…')}</p></div></section>`;
  const page=$('[data-inventory]'),priceInput=$('#sell-price'),amountInput=$('#sell-amount'),submit=$('#sell-submit'),max=$('#sell-max'),status=$('#market-status');
  const alive=()=>page.isConnected;
  const showTab=()=>{app.querySelectorAll('[data-trade]').forEach(b=>b.classList.toggle('active',b.dataset.trade===draft.tab));app.querySelectorAll('[data-pane]').forEach(p=>p.hidden=p.dataset.pane!==draft.tab);};
  app.querySelectorAll('[data-trade]').forEach(b=>b.onclick=()=>{draft.tab=b.dataset.trade;showTab();});showTab();
  function validate(){
    if(!alive())return;
    $('#sell-available').textContent=!account?t('Connect your wallet to see what you can sell.','连接钱包以查看可出售的组件。'):available===null?t('Checking your available balance…','正在检查可用余额…'):t('Available to sell: ','可出售：')+available.toLocaleString('en-US')+' '+names[id];
    max.disabled=available===null||available===0n||listingInProgress;
    amountInput.disabled=priceInput.disabled=listingInProgress;
    let valid=false,message='';
    if(account&&available!==null){
      if(available===0n)message=t('No '+names[id]+' available in this wallet. Choose another part above or mint more.','此钱包没有可用的 '+names[id]+'。请选择上方其他组件或继续铸造。');
      else if(!/^[1-9]\d*$/.test(draft.quantity))message=t('Enter a whole quantity greater than zero.','请输入大于零的整数数量。');
      else if(BigInt(draft.quantity)>available)message=t('Quantity exceeds your available balance.','数量超过可用余额。');
      else if(draft.price){try{listingValues(draft.quantity,draft.price,available);valid=true;}catch{message=t('Enter a positive ETH price with up to 18 decimal places.','请输入正数 ETH 价格，最多 18 位小数。');}}
    }
    $('#sell-validation').textContent=message;
    submit.disabled=listingInProgress||(!!account&&!valid);
    submit.textContent=listingInProgress?t('Waiting for confirmation…','等待确认…'):account?t('Approve and list','授权并挂单'):t('Connect wallet','连接钱包');
  }
  priceInput.oninput=()=>{draft.price=priceInput.value.trim();validate();};amountInput.oninput=()=>{draft.quantity=amountInput.value.trim();validate();};
  max.onclick=()=>{if(available!==null){draft.quantity=String(available);amountInput.value=draft.quantity;validate();}};
  const reload=attachWalletParts(project,rows=>{available=rows&&!rows[id].error?rows[id].amount:null;validate();if(rows?.[id].error)$('#sell-available').textContent=t('Balance unavailable. Use Refresh balances before selling.','余额暂不可用，请先刷新余额再出售。');});
  validate();
  $('#listing-box').onclick=e=>{const b=e.target.closest('[data-buy-listing]');if(b)buyListing(id,b.dataset.buyListing,b.dataset.buyAmount,b.dataset.buyPrice);};
  loadChainListings(id);
  submit.onclick=async()=>{
    if(listingInProgress)return;
    if(!account){await connect().catch(error);return;}
    const sender=account,values={...draft};
    const setStatus=text=>{if(status.isConnected)status.textContent=text;};
    listingInProgress=true;validate();
    try{
      await ensureNetwork();
      const assertSender=async()=>{const authorized=await provider.request({method:'eth_accounts'});if(!account||account.toLowerCase()!==sender.toLowerCase()||authorized[0]?.toLowerCase()!==sender.toLowerCase()||Number(await provider.request({method:'eth_chainId'}))!==c.chainId)throw Error(t('Wallet account or network changed. Please retry.','钱包账户或网络已更改，请重试。'));};
      const current=await readParts({call,partsAddress:c.partsAddress,owner:sender});
      const {amount,price}=listingValues(values.quantity,values.price,current[id].amount);
      const ownerWord=sender.slice(2).toLowerCase().padStart(64,'0'),marketWord=c.marketAddress.slice(2).toLowerCase().padStart(64,'0');
      const send=async(to,data)=>{await assertSender();const tx={from:sender,to,data,value:'0x0'};const gas=BigInt(await provider.request({method:'eth_estimateGas',params:[tx]}));tx.gas=hex(gas*120n/100n);tx.gasPrice=await provider.request({method:'eth_gasPrice'});await assertSender();return provider.request({method:'eth_sendTransaction',params:[tx]});};
      const approved=BigInt(await call(c.partsAddress,'0xe985e9c5'+ownerWord+marketWord));
      if(!approved){setStatus(t('Confirm token approval in your wallet…','请在钱包中确认代币授权…'));const hash=await send(c.partsAddress,'0xa22cb465'+marketWord+word(1));if(Number((await waitReceipt(hash)).status)!==1)throw Error(t('Token approval failed.','代币授权失败。'));}
      const fresh=await readParts({call,partsAddress:c.partsAddress,owner:sender});listingValues(values.quantity,values.price,fresh[id].amount);
      setStatus(t('Confirm listing in your wallet…','请在钱包中确认挂单…'));
      const hash=await send(c.marketAddress,'0xb03053b6'+word(id)+word(amount)+word(price));
      setStatus(t('Listing submitted. Waiting for confirmation…','挂单已提交，等待确认…'));
      const receipt=await waitReceipt(hash);if(Number(receipt.status)!==1)throw Error(t('Listing reverted. Your parts were not listed.','挂单已回滚，组件未上架。'));
      setStatus(t('Listing confirmed. Your available balance has been updated.','挂单已确认，可用余额已更新。'));toast('Listing confirmed.','挂单已确认。');
      if(alive()){await reload();listingCursor=null;listingPages=[];await loadChainListings(id);}
    }catch(e){setStatus(t('Listing not completed. Check any submitted transaction before retrying.','挂单未完成，请先检查已提交的交易再重试。'));error(e);}
    finally{listingInProgress=false;if(alive())validate();else if(/^market-(openbook|fillout)/.test(route()))render();}
  };
}

let fillingCircuit=false;
async function createCircuit(binary,quotes,settles,project){const config=projectConfigs[project];if(!config)throw Error(t("Choose a project first.","请先选择项目。"));if(fillingCircuit)return;fillingCircuit=true;const lock=()=>{const b=$('#create-circuit');if(b){b.disabled=true;b.textContent=t('Waiting for wallet…','等待钱包…');}};lock();try{if(!account)await connect();await ensureNetwork();lock();const sender=account;for(const [id,needed] of [[0,quotes],[1,settles]]){const balance=BigInt(await rpc('eth_call',[{to:config.partsAddress,data:'0x00fdd58e'+sender.slice(2).padStart(64,'0')+word(id)},'latest']));if(balance<BigInt(needed))throw Error(t('Insufficient ','余额不足：')+names[id]+t(': need ','，需要 ')+needed);}
const op=config.circuitsAddress.slice(2).padStart(64,'0');const approved=BigInt(await rpc('eth_call',[{to:config.partsAddress,data:'0xe985e9c5'+sender.slice(2).padStart(64,'0')+op},'latest']));
async function send(to,data){if((await provider.request({method:'eth_accounts'}))[0]?.toLowerCase()!==sender.toLowerCase())throw Error(t("Wallet account changed.","钱包账户已更改。"));await ensureNetwork();const tx={from:sender,to,data,value:'0x0'};const estimate=BigInt(await provider.request({method:'eth_estimateGas',params:[tx]}));tx.gas=hex(estimate*120n/100n);tx.gasPrice=await provider.request({method:'eth_gasPrice'});await assertWalletContext(sender,config.chainId);return provider.request({method:'eth_sendTransaction',params:[tx]});}
if(!approved){toast('Approve parts access for the circuit contract.','请授权电路合约使用组件。');const approval=await send(config.partsAddress,'0xa22cb465'+op+word(1));if(Number((await waitReceipt(approval)).status)!==1)throw Error(t("Approval failed.","授权失败。"));}
const bytes=binary.slice(2);const data='0xaf0a675b'+word(32)+word(bytes.length/2)+bytes.padEnd(Math.ceil(bytes.length/64)*64,'0');const hash=await send(config.circuitsAddress,data);toast('Circuit submitted. Waiting for confirmation…','电路已提交，等待确认…');const receipt=await waitReceipt(hash);if(Number(receipt.status)!==1)throw Error(t("Circuit creation reverted.","电路创建已回滚。"));toast('Circuit NFT created. Parts permanently locked.','电路 NFT 已创建，组件已永久锁定。');await refresh();const status=$('#studio-error');if(status)status.innerHTML='<a target="_blank" rel="noopener" href="'+config.explorerUrl+'/tx/'+hash+'">'+t('Circuit confirmed · View transaction','电路已确认 · 查看交易')+'</a>'; }catch(e){error(e);}finally{fillingCircuit=false;const b=$('#create-circuit');if(b){b.disabled=false;b.textContent=t('Create circuit NFT','创建电路 NFT');}}}
function render(){if(!config)return;const k=currentProject();if(projectConfigs&&config.partsAddress!==projectConfigs[k].partsAddress){config={...projectConfigs[k]};readId++;chain=null;balances=null;queueMicrotask(refresh);}header();const r=route();if(r==='studio')mountStudio(app,createCircuit);else if(/^market-(openbook|fillout)-[01]$/.test(r))marketDetail(r.replace('market-',''));else if(r==='market-openbook'||r==='market-fillout')marketDetail(r.replace('market-','')+'-0');else if(/^(fillout|openbook)-[01]$/.test(r))mintPage(Number(r.at(-1)),r.split('-')[0]);else if(/^mint-[01]$/.test(r))mintPage(Number(r.at(-1)));else if(r==='foundry')mintPage(0);else ({projects,market,data:dataPage,wallet:holdings,airdrop:holdings,whitepaper,guide:whitepaper}[r]||projects)();if(loadError&&/^(?:(?:fillout|openbook|mint)-[01]|foundry|data)$/.test(r)){const p=document.createElement('p');p.className='alert';p.textContent=t('Live data temporarily unavailable. Retry in a moment. Your wallet connection is unchanged.','实时数据暂不可用，请稍后重试。钱包连接未改变。');app.prepend(p);}}
window.addEventListener('hashchange',render);
window.addEventListener('ethereum#initialized',()=>walletSession.restore());
window.addEventListener('focus',()=>walletSession.restore());
document.addEventListener('visibilitychange',()=>{if(!document.hidden)walletSession.restore();});
try{
  config=await fetch('config.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('Configuration unavailable');return r.json();});
  projectConfigs={openbook:Object.freeze({...config}),fillout:Object.freeze({...config,...config.fillout})};
  render();walletSession.restore();await refresh();
}catch(e){app.textContent=t('Unable to load the app. Please reload.','无法加载应用，请刷新页面。');}
